import type {
  IdentityStatusChange,
  RoomInterface,
  TaskHandleInterface,
} from "@unomed/react-native-matrix-sdk";
import { IdentityState } from "@unomed/react-native-matrix-sdk";
import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
import { useEffect, useState } from "react";
import { offlineToastHelper } from "shared/utils";

type ViolationRecord = Record<string, "pin" | "verification">;

export const useRoomIdentityViolations = (room: RoomInterface | null) => {
  const [violations, setViolations] = useState<ViolationRecord>({});
  const [violatingUsers, setViolatingUsers] = useState<ViolatingUser[]>([]);
  const [isPinViolatingUsersLoading, setIsPinViolatingUsersLoading] =
    useState(false);

  useEffect(() => {
    const userIds = Object.keys(violations);
    if (!userIds.length) {
      setViolatingUsers([]);
      return;
    }

    Promise.all(
      userIds.map(async (userId) => {
        try {
          const profile = await MatrixCore.instance?.getProfile(userId);
          return {
            userId,
            displayName: profile?.displayName || userId,
            avatarUrl: profile?.avatarUrl || null,
            violationType: violations[userId],
          } satisfies ViolatingUser;
        } catch {
          return {
            userId,
            displayName: userId,
            avatarUrl: null,
            violationType: violations[userId],
          } satisfies ViolatingUser;
        }
      }),
    ).then(setViolatingUsers);
  }, [violations]);

  useEffect(() => {
    if (!room) return;

    let handle: TaskHandleInterface | null = null;

    room
      .subscribeToIdentityStatusChanges({
        call(changes: Array<IdentityStatusChange>) {
          setViolations((prev) => {
            const next = { ...prev };
            for (const change of changes) {
              if (change.changedTo === IdentityState.PinViolation) {
                next[change.userId] = "pin";
              } else if (
                change.changedTo === IdentityState.VerificationViolation
              ) {
                next[change.userId] = "verification";
              } else {
                delete next[change.userId];
              }
            }
            return next;
          });
        },
      })
      .then((h) => {
        handle = h;
      })
      .catch(console.error);

    return () => {
      handle?.cancel();
    };
  }, [room]);

  // Resolves each violation with the correct SDK call:
  // - PinViolation → pin() acknowledges the new identity
  // - VerificationViolation → withdrawVerification() downgrades trust to pinned
  const pinViolatingUsers = async () => {
    try {
      setIsPinViolatingUsersLoading(true);
      const encryption = MatrixCore.getClient().encryption();

      await Promise.all(
        Object.entries(violations).map(async ([userId, violationType]) => {
          try {
            const identity = await encryption.userIdentity(userId, true);
            if (!identity) return;
            if (violationType === "verification") {
              await identity.withdrawVerification();
            } else {
              await identity.pin();
            }
          } catch (error) {
            console.error(`Failed to resolve identity for ${userId}:`, error);
          }
        }),
      );
    } catch (error) {
      offlineToastHelper("Failed to dismiss message.");
      console.error("Failed to resolve identity violations:", error);
    } finally {
      setIsPinViolatingUsersLoading(false);
    }
  };

  return { isPinViolatingUsersLoading, violatingUsers, pinViolatingUsers };
};

